class Device {
    let name: String
    init(_ name: String) { self.name = name }
    deinit { print("\(name) deallocated") }
}

var phone: Device? = Device("iPhone")
weak var weakPhone = phone
phone = nil
print("Is nil: \(weakPhone == nil)")

