class TaskItem {
    let title: String
    init(title: String) { self.title = title }
    deinit { print("Task \(title) done") }
}

class Project {
    unowned let task: TaskItem
    init(task: TaskItem) { self.task = task }
}

var item: TaskItem? = TaskItem(title: "Design")
var proj: Project? = Project(task: item!)
print("Task in project: \(proj?.task.title ?? "")")
proj = nil
item = nil

