class Profile {
    let name: String
    init(name: String) {
        self.name = name
    }
    deinit {
        print("Profile \(name) freed")
    }
}

class Subscription {
    weak var user: Profile?
    init(user: Profile?) {
        self.user = user
    }
}

var p: Profile? = Profile(name: "Taylor")
let sub = Subscription(user: p)
print("Before: \(sub.user?.name ?? "none")")
p = nil
print("After: \(sub.user?.name ?? "none")")

class Author {
    let name: String
    var book: Book?
    init(name: String) {
        self.name = name
    }
    deinit {
        print("Author \(name) deallocated")
    }
}

class Book {
    let title: String
    unowned let author: Author
    init(title: String, author: Author) {
        self.title = title
        self.author = author
    }
    deinit {
        print("Book \(title) deallocated")
    }
}

var author: Author? = Author(name: "Jane")
author?.book = Book(title: "Novel", author: author!)
print("Author has book: \(author?.book?.title ?? "")")
author = nil
print("Finished author test")

protocol TaskDelegate: AnyObject {
    func taskDidFinish()
}

class TaskRunner {
    weak var delegate: TaskDelegate?
    func complete() {
        delegate?.taskDidFinish()
    }
}

class Coordinator: TaskDelegate {
    func taskDidFinish() {
        print("Task finished callback received")
    }
    deinit {
        print("Coordinator deallocated")
    }
}

let runner = TaskRunner()
var coordinator: Coordinator? = Coordinator()
runner.delegate = coordinator
runner.complete()
coordinator = nil
print("Delegate after nil: \(runner.delegate == nil)")
